import Member from '../models/Member.js'; import Loan from '../models/Loan.js'; import {audit} from '../utils/audit.js';
export async function listMembers(req,res){const q=String(req.query.q||'').trim();const filter=q?{$or:[{name:{$regex:q,$options:'i'}},{memberId:{$regex:q,$options:'i'}},{email:{$regex:q,$options:'i'}},{phone:{$regex:q,$options:'i'}}]}:{};res.json(await Member.find(filter).sort({name:1}));}
export async function createMember(req,res){if(!req.body.memberId?.trim()||!req.body.name?.trim())return res.status(400).json({message:'Member ID and name are required'});const m=await Member.create(req.body);await audit(req.user.id,'Created member','Member',m._id.toString(),m.name);res.status(201).json(m);}
export async function updateMember(req,res){const m=await Member.findByIdAndUpdate(req.params.id,req.body,{new:true,runValidators:true});if(!m)return res.status(404).json({message:'Member not found'});await audit(req.user.id,'Updated member','Member',m._id.toString(),m.name);res.json(m);}
export async function deleteMember(req,res){const active=await Loan.exists({member:req.params.id,status:'issued'});if(active)return res.status(400).json({message:'Member has active loans and cannot be deleted'});const m=await Member.findByIdAndDelete(req.params.id);if(!m)return res.status(404).json({message:'Member not found'});await audit(req.user.id,'Deleted member','Member',req.params.id,m.name);res.json({message:'Member deleted'});}
